// Fan out: each query becomes 3 sample runs.
// LLM outputs are stochastic, so a single ask tells you almost nothing.
// We measure inclusion RATE across samples.
const SAMPLES_PER_QUERY = 3;
const out = [];
for (const item of $input.all()) {
  for (let i = 1; i <= SAMPLES_PER_QUERY; i++) {
    out.push({
      json: {
        query_id: item.json.query_id,
        query: item.json.query,
        brand: item.json.brand,
        competitors: item.json.competitors || '',
        sample: i,
        total_samples: SAMPLES_PER_QUERY
      }
    });
  }
}
return out;

