// Parse judge output and attach run metadata
const meta = $('Loop Over Sample Batches').item.json;
let judged = {};
try {
  judged = JSON.parse($json.choices[0].message.content);
} catch (e) {
  judged = { brand_mentioned: false, mention_rank: null, sentiment: null, recommended: false, competitors_mentioned: [], parse_error: true };
}
return [{ json: { ...meta, ...judged } }];

// Aggregate samples per query into a 0-100 visibility score.
// Weights: inclusion rate 50 | mention position 25 | sentiment 25
const byQuery = {};
for (const item of $input.all()) {
  const j = item.json;
  if (!byQuery[j.query_id]) byQuery[j.query_id] = { meta: j, runs: [] };
  byQuery[j.query_id].runs.push(j);
}
const today = new Date().toISOString().slice(0, 10);
const out = [];
for (const qid of Object.keys(byQuery)) {
  const { meta, runs } = byQuery[qid];
  const n = runs.length;
  const mentioned = runs.filter(r => r.brand_mentioned);
  const inclusionRate = mentioned.length / n;

  // Position: rank 1 = 1.0, rank 2 = 0.5, rank 3 = 0.33 ...
  const rankScores = mentioned.map(r => (r.mention_rank ? 1 / r.mention_rank : 0));
  const avgRankScore = rankScores.length ? rankScores.reduce((a, b) => a + b, 0) / rankScores.length : 0;
  const avgRank = mentioned.length ? (mentioned.reduce((a, r) => a + (r.mention_rank || 0), 0) / mentioned.length).toFixed(1) : '';

  // Sentiment: positive 1, neutral 0.5, negative 0
  const sentMap = { positive: 1, neutral: 0.5, negative: 0 };
  const sentScores = mentioned.map(r => sentMap[r.sentiment] ?? 0.5);
  const avgSent = sentScores.length ? sentScores.reduce((a, b) => a + b, 0) / sentScores.length : 0;

  const score = Math.round(inclusionRate * 50 + avgRankScore * 25 + avgSent * 25);

  const compsSeen = [...new Set(runs.flatMap(r => r.competitors_mentioned || []))].join(', ');

  out.push({ json: {
    run_date: today,
    query_id: qid,
    query: meta.query,
    brand: meta.brand,
    runs: n,
    inclusion_rate: (inclusionRate * 100).toFixed(0) + '%',
    avg_rank: avgRank,
    avg_sentiment: sentScores.length ? avgSent.toFixed(2) : '',
    visibility_score: score,
    competitors_seen: compsSeen
  } });
}
return out;
